const cands = []; let depth = 0, start = -1, inStr = false, esc = false;
for (let i = 0; i < output.length; i++) {
  const c = output[i];
  if (depth === 0) { if (c === '{') { depth = 1; start = i; inStr = false; esc = false; } continue; }
  if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
  if (c === '"') { inStr = true; continue; }
  if (c === '{') { depth++; }
  else if (c === '}' && --depth === 0) { cands.push(output.slice(start, i + 1)); inStr = false; esc = false; }
}
let obj = null;
for (let i = cands.length - 1; i >= 0 && obj === null; i--) {
  try { obj = JSON.parse(cands[i]); } catch (e) { /* 不是完整物件，往前試 */ }
}
return obj?.items?.[0]?.sweetness === 50;

